def _parse_entry_allowed_symbols(raw: str) -> set[str]:
    out: set[str] = set()
    for tok in str(raw or "").split(","):
        sym = str(tok or "").strip().upper().replace("-", "/")
        if not sym:
            continue
        if "/" not in sym and sym.endswith("USDT"):
            sym = f"{sym[:-4]}/USDT"
        out.add(normalize_symbol(sym))
    return out


